if (w === '2h') { now.setHours(now.getHours() + 2); postAt = now.toISOString(); }
else if (w === 'tomorrow_12') { const t = new Date(); t.setDate(t.getDate() + 1); t.setHours(12, 0, 0, 0); postAt = t.toISOString(); }
else { postAt = now.toISOString(); }
return [{ json: { post_at: postAt } }];

